open(os.path.join(ROOT, 'js', 'data.js'), 'w', encoding='utf-8').write('/* Kisti v6 · shared data (gallery, labels, credits). Script data: data-op.js, data-pa.js, data-av.js (tools/build_data.py). */\nwindow.KISTI = ' + json.dumps(K, ensure_ascii=False, indent=1) + ';\n')
